  State<MainView> createState\(\) => _MainViewState\(\);
}

class _MainViewState extends State<MainView> {
  int _currentIndex = 0;

  final List<Widget> _pages = const [
    HomeView\(\),
    MascotView\(\),
    StatisticsView\(\),
    SettingsView\(\),
  ];

  @override
  Widget build\(BuildContext context\) {
    return Scaffold\(
      body: IndexedStack\(
        index: _currentIndex,
        children: _pages,
